def px2m(P, px, py):
    h = math.radians(P["head"]); sx = (px - P["cx"]) * P["mpp"]; sy = (P["cy"] - py) * P["mpp"]
    e = sx * math.cos(h) + sy * math.sin(h); n = -sx * math.sin(h) + sy * math.cos(h)
    ox = (P["lon"] - LON0) * MLON; oy = (P["lat"] - LAT0) * MLAT
    return round(ox + e, 1), round(oy + n, 1)
if __name__ == "__main__":
    out = {"ruas": {}, "casas": [], "pontos": {}}
    for cod, P in PRINTS.items():
        for n, pts in P["ruas"].items(): out["ruas"][cod + " " + n] = [px2m(P, *p) for p in pts]
        for (px, py, w, d) in P["casas"]: x, y = px2m(P, px, py); out["casas"].append([cod, x, y, round(w * P["mpp"], 1), round(d * P["mpp"], 1)])
        for n, p in P["pontos"].items(): out["pontos"][n] = px2m(P, *p)
    json.dump(out, open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "ok-leitura.json"), "w"), ensure_ascii=False, indent=1)
    for k, v in out["ruas"].items(): print(k, v)
    print(len(out["casas"]), "casas;", out["pontos"])
